54	export function sanitizeContactTheatreState(
55	  state: Record<string, unknown> | null,
56	): Record<string, unknown> | null {
57	  if (!state) return null;
58	  const sheetsByIdValue = state.sheetsById;
59	  if (
60	    sheetsByIdValue == null ||
61	    typeof sheetsByIdValue !== "object" ||
62	    Array.isArray(sheetsByIdValue)
63	  ) {
64	    return state;
65	  }
66	  const sheetsById = sheetsByIdValue as Record<string, unknown>;
67	  const nextSheetsById: Record<string, unknown> = {};
68	  CONTACT_THEATRE_SHEET_IDS.forEach((sheetId) => {
69	    if (!Object.prototype.hasOwnProperty.call(sheetsById, sheetId)) return;
70	    nextSheetsById[sheetId] = sheetsById[sheetId];
71	  });
72	  return {
73	    ...state,
74	    sheetsById: nextSheetsById,
75	  };
76	}
