78	export function resolveContactAuthorMode(): boolean {
79	  return EnvSetup.hasQueryFlag(
80	    CONTACT_THEATRE_QUERY_KEY,
81	    CONTACT_THEATRE_QUERY_ENABLED,
82	  );
83	}
