438	  private _resolveSheetEndPosition(
439	    sheetId: ContactTheatreSheetId,
440	    sequence: ContactTheatreSequence,
441	  ): number {
442	    const saveFile = TheatreStudioService.createContentOfSaveFile(
443	      CONTACT_THEATRE_PROJECT_ID,
444	    );
445	    const sheetsById = readContactRecord(saveFile?.sheetsById);
446	    const sheetState = readContactRecord(sheetsById?.[sheetId]);
447	    const sequenceState = readContactRecord(sheetState?.sequence);
448	    const tracksByObject = readContactRecord(sequenceState?.tracksByObject);
449	    const objectTracks = readContactRecord(
450	      tracksByObject?.[CONTACT_THEATRE_OBJECT_ID],
451	    );
452	    const trackData = readContactRecord(objectTracks?.trackData);
453	    if (!trackData) {
454	      return sequence.length > 0 ? sequence.length : 0;
455	    }
456	
457	    let maxPosition = Number.NEGATIVE_INFINITY;
458	    Object.values(trackData).forEach((trackState) => {
459	      const trackRecord = readContactRecord(trackState);
460	      const keyframes = trackRecord?.keyframes;
461	      if (!Array.isArray(keyframes)) return;
462	      keyframes.forEach((keyframe) => {
463	        const keyframeRecord = readContactRecord(keyframe);
464	        const position = keyframeRecord?.position;
465	        if (typeof position !== "number") return;
466	        if (!Number.isFinite(position)) return;
467	        maxPosition = Math.max(maxPosition, position);
468	      });
469	    });
470	
471	    if (!Number.isFinite(maxPosition)) {
472	      return sequence.length > 0 ? sequence.length : 0;
473	    }
474	    return maxPosition;
475	  }
