160	        y: this._toFinite(rotation.y, fallback.rotation.y),
161	        z: this._toFinite(rotation.z, fallback.rotation.z),
162	      },
163	      scale: {
164	        x: this._toFinite(target?.scale.x, fallback.scale.x),
165	        y: this._toFinite(target?.scale.y, fallback.scale.y),
166	        z: this._toFinite(target?.scale.z, fallback.scale.z),
167	      },
168	      visible: target?.visible ?? fallback.visible,
169	    };
